<x-admin-layout title="Customers"><form class="inline-form"><input name="q" value="{{ request('q') }}" aria-label="Search customers" placeholder="Name or email"><button class="button">Search</button></form><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Orders</th><th>Access</th></tr></thead><tbody>@foreach($customers as $u)<tr><td>{{ $u->name }}</td><td>{{ $u->email }}<small>{{ $u->phone }}</small></td><td><a href="/admin/orders?customer={{ $u->id }}">{{ $u->orders_count }} orders ↗</a></td><td>@if(auth()->user()->role==='owner' && $u->role!=='owner')<form method="post" action="/admin/customers/{{ $u->id }}" class="inline-form">@csrf<select name="role" aria-label="Role for {{ $u->name }}"><option value="customer" @selected($u->role==='customer')>Customer</option><option value="admin" @selected($u->role==='admin')>Admin</option></select><select name="active" aria-label="Account status"><option value="1" @selected($u->active)>Active</option><option value="0" @selected(!$u->active)>Disabled</option></select><button data-confirm="Change this account’s access?">Save</button></form>@else{{ $u->role }} · {{ $u->active?'active':'disabled' }}@endif</td></tr>@endforeach</tbody></table></div>{{ $customers->links() }}</x-admin-layout>